using ProjectTask.DTO; using ProjectTask.DAL; using System.Data;
namespace ProjectTask.BUS;
public class ProjectService {readonly ProjectRepository repo=new();public Task<List<Project>> GetAllAsync()=>repo.GetAllAsync();public Task SaveAsync(Project p,bool isNew){if(string.IsNullOrWhiteSpace(p.TenDuAn))throw new ArgumentException("Tên dự án không được để trống.");if(p.NgayBatDau.HasValue&&p.NgayKetThuc.HasValue&&p.NgayKetThuc<p.NgayBatDau)throw new ArgumentException("Ngày kết thúc phải sau ngày bắt đầu.");return repo.SaveAsync(p,isNew);}public Task DeleteAsync(int id)=>repo.DeleteAsync(id);}
public class MemberService {readonly MemberRepository repo=new();public Task<List<Member>> GetAllAsync()=>repo.GetAllAsync();}
public class TaskService {readonly TaskRepository repo=new();public Task<List<TaskItem>> GetAllAsync(int p=0,string s="")=>repo.GetAllAsync(p,s);public Task SaveAsync(TaskItem t,bool n){if(t.MaDuAn<=0)throw new ArgumentException("Hãy chọn dự án.");if(string.IsNullOrWhiteSpace(t.TenTask))throw new ArgumentException("Tên công việc không được để trống.");return repo.SaveAsync(t,n);}public Task DeleteAsync(int id)=>repo.DeleteAsync(id);public Task UpdateStatusAsync(int id,string s)=>repo.UpdateStatusAsync(id,s);public Task AssignAsync(int t,int m)=>repo.AssignAsync(t,m);public Task<DataTable> GetOverdueAsync()=>repo.GetOverdueAsync();public Task<DataTable> GetStatsAsync(int p)=>repo.GetStatsAsync(p);}
